const slug=new URLSearchParams(location.search).get('slug');
const p=data.find(item=>item.slug===slug);
const main=document.getElementById('main');
function esc(s){return String(s).replace(/[&<>"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[ch]));}
if(!p){main.innerHTML='<section class="container project-hero"><h1>Project not found.</h1><a href="index.html#work">← Return to selected work</a></section>';}else{
 document.title=p.title+' | Zainab Abadi';
 let toc=p.sections.map(([title],i)=>'<li><a href="#section-'+(i+1)+'">'+esc(title)+'</a></li>').join('');
 const rich=items=>(Array.isArray(items)?items:[items]).map(it=>Array.isArray(it)?'<ul>'+it.map(li=>'<li>'+esc(li)+'</li>').join('')+'</ul>':'<p>'+esc(it)+'</p>').join('');
 const plain=items=>(Array.isArray(items)?items:[items]).map(it=>Array.isArray(it)?it.join(' '):it).join(' ');
 const blocks=p.sections.map(([title,items],i)=>'<section id="section-'+(i+1)+'" class="study-section"><h2>'+esc(title)+'</h2>'+rich(items)+'</section>').join('');
 const m=media[p.slug];
 const imgSrc=f=>'assets/'+encodeURIComponent(f);
 const caption=(label,text)=>'<figcaption><span class="evidence-kind">'+esc(label)+'</span><span class="evidence-text">'+esc(text)+'</span></figcaption>';
 const pic=([f,label,text,alt])=>'<a href="'+imgSrc(f)+'" target="_blank" rel="noopener noreferrer"><img loading="lazy" src="'+imgSrc(f)+'" alt="'+esc(alt||(label+': '+text))+'"></a>';
 const slide=(it,i,n)=>'<figure class="gal-slide" role="group" aria-roledescription="slide" aria-label="'+(i+1)+' of '+n+'">'+pic(it)+caption(it[1],it[2])+'</figure>';
 const arrow=d=>'<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+d+'"/></svg>';
 const carousel=(items,label,per)=>'<div class="gallery gallery-per-'+per+'" role="group" aria-roledescription="carousel" aria-label="'+esc(label)+'"><div class="gallery-track" tabindex="0" aria-label="'+esc(label)+', scroll sideways or use the arrow keys">'+items.map((it,i)=>slide(it,i,items.length)).join('')+'</div><div class="gallery-bar"><button type="button" class="gal-btn gal-prev" aria-label="Previous image">'+arrow('M15 5l-7 7 7 7')+'</button><p class="gal-count" aria-live="polite"></p><button type="button" class="gal-btn gal-next" aria-label="Next image">'+arrow('M9 5l7 7-7 7')+'</button></div></div>';
 const lead=m.lead?'<figure class="evidence-lead">'+pic(m.lead)+caption(m.lead[1],m.lead[2])+'</figure>':'';
 const gallery=carousel(m.gallery,'Evidence images',1);
 const responsive=m.responsive?'<h3 class="evidence-sub">'+esc(m.responsive.title)+'</h3>'+m.responsive.devices.map(d=>'<div class="device-block"><h4>'+esc(d.name)+'</h4>'+carousel(d.items,d.name+' layouts',d.per)+'</div>').join(''):'';
 const next=data[(data.indexOf(p)+1)%data.length];
 const words=t=>String(t).split(/\s+/).filter(Boolean).length;
 const quickMin=Math.max(1,Math.ceil([p.context,p.roleDetail,p.approach,p.outcomeDetail,p.impact].map(plain).concat(p.decisions.map(d=>d.join(' '))).reduce((n,t)=>n+words(t),0)/200));
 const deepMin=Math.max(1,Math.ceil(p.sections.reduce((n,s)=>n+words(plain(s[1])),0)/200));
 const factsHtml='<dl class="facts">'+p.facts.map(([k,v])=>'<div><dt>'+esc(k)+'</dt><dd>'+(Array.isArray(v)?'<ul>'+v.map(li=>'<li>'+esc(li)+'</li>').join('')+'</ul>':esc(v))+'</dd></div>').join('')+'</dl>';
 const decisionsHtml='<h3 class="decisions-title">Three decisions behind the work</h3><ol class="decisions">'+p.decisions.map(([t,d],i)=>'<li><span class="decision-n" aria-hidden="true">0'+(i+1)+'</span><h4>'+esc(t)+'</h4><p>'+esc(d)+'</p></li>').join('')+'</ol>';
 main.innerHTML='<section class="container project-hero"><a class="underlined" href="index.html#work">← All projects</a><p class="eyebrow" style="margin-top:40px">'+esc(p.year)+' / Case study</p><h1>'+esc(p.title)+'</h1><p class="lede">'+esc(p.lede)+'</p><ul class="chips chips-lg" aria-label="Topics">'+p.tags.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul></section><div class="container"><div class="cover"><img src="assets/'+encodeURIComponent(p.img)+'" alt="'+esc(p.imgAlt)+'"></div></div><section class="container quick-scan-wrap" aria-labelledby="quick-title"><div class="quick-scan-head"><div><div class="eyebrow">Quick scan · '+quickMin+' min read</div><h2 id="quick-title">At a glance</h2></div><a href="#case-study" class="jump-link">Read the full story ↓</a></div>'+factsHtml+'<div class="quick-summary"><div class="quick-cell"><h3>Context & challenge</h3><p>'+esc(p.context)+'</p></div><div class="quick-cell"><h3>My role</h3>'+rich(p.roleDetail)+'</div><div class="quick-cell"><h3>Approach & evidence</h3>'+rich(p.approach)+'</div><div class="quick-cell"><h3>Outcome & deliverables</h3>'+rich(p.outcomeDetail)+'</div><div class="quick-cell impact-cell"><h3>What changed</h3><p>'+esc(p.impact)+'</p></div></div>'+decisionsHtml+'</section><div id="case-study" class="container study-layout"><aside class="study-toc"><div class="eyebrow">Deep dive · '+deepMin+' min read</div><h2>In this case study</h2><nav aria-label="Case study contents"><ol>'+toc+'<li><a href="#evidence">Evidence and communication</a></li></ol></nav><a class="jump-link" href="#quick-title">↑ Back to overview</a></aside><article class="study-body">'+blocks+'<blockquote class="takeaway"><p>'+esc(p.takeaway)+'</p></blockquote><section id="evidence" class="study-section"><h2>Evidence and communication</h2><p>The artefacts behind the work, and the slides I used to present it. The slides come from internal presentations to the teams involved, so some of the text is in Spanish. Click any image to see it larger.</p>'+(p.doc?'<p class="evidence-doc"><a href="'+esc(p.doc[0])+'" target="_blank" rel="noopener noreferrer">'+esc(p.doc[1])+'</a> '+esc(p.doc[2])+'</p>':'')+lead+gallery+responsive+'</section><p class="note">'+esc(p.note)+'</p></article></div><div class="container section"><a class="next-project" href="project.html?slug='+encodeURIComponent(next.slug)+'"><div><div class="eyebrow">Next case study</div><h2>'+esc(next.title)+'</h2></div><span class="button">View project ↗</span></a></div>';

 const calm=matchMedia('(prefers-reduced-motion: reduce)').matches;
 document.querySelectorAll('.gallery').forEach(g=>{
  const t=g.querySelector('.gallery-track'),prev=g.querySelector('.gal-prev'),next=g.querySelector('.gal-next'),count=g.querySelector('.gal-count'),slides=[...t.children];
  const step=()=>slides.length>1?slides[1].offsetLeft-slides[0].offsetLeft:t.clientWidth;
  const update=()=>{const max=t.scrollWidth-t.clientWidth,moves=max>2;g.classList.toggle('is-static',!moves);if(!moves)return;const i=Math.min(slides.length-1,Math.round(t.scrollLeft/step()));count.textContent=(i+1)+' of '+slides.length;prev.disabled=t.scrollLeft<=2;next.disabled=t.scrollLeft>=max-2;};
  const go=d=>t.scrollBy({left:d*step(),behavior:calm?'auto':'smooth'});
  prev.addEventListener('click',()=>go(-1));next.addEventListener('click',()=>go(1));
  t.addEventListener('scroll',update,{passive:true});
  addEventListener('resize',update);t.querySelectorAll('img').forEach(im=>im.addEventListener('load',update));update();
 });
}
